<?php
if(!defined('ABSPATH'))exit;
/** TUFF BEATZ Studio Business OS V14.5.1 — Versioned Opportunity Contract Workflow + acceptance integrity */
function tuff_beatz_v145_contract_data($id){$c=get_post_meta((int)$id,'_tb_v145_contract',true);return is_array($c)?$c:array();}
function tuff_beatz_v145_contract_acceptance($id){$a=get_post_meta((int)$id,'_tb_v145_contract_acceptance',true);return is_array($a)?$a:array();}
function tuff_beatz_v145_contract_acceptance_history($id){$h=get_post_meta((int)$id,'_tb_v145_contract_acceptance_history',true);return is_array($h)?$h:array();}
function tuff_beatz_v145_contract_token($id){$t=(string)get_post_meta((int)$id,'_tb_v145_contract_token',true);if(!$t){$t=wp_generate_password(32,false,false);update_post_meta((int)$id,'_tb_v145_contract_token',$t);}return $t;}
function tuff_beatz_v145_contract_url($id){return add_query_arg(array('opportunity'=>(int)$id,'contract_token'=>rawurlencode(tuff_beatz_v145_contract_token($id))),home_url('/contract/'));}
function tuff_beatz_v145_contract_setup(){if(!get_page_by_path('contract')){$id=wp_insert_post(array('post_title'=>'Contract','post_name'=>'contract','post_status'=>'publish','post_type'=>'page','post_content'=>''));if(!is_wp_error($id)&&$id)update_post_meta($id,'_wp_page_template','page-contract.php');}}
add_action('init','tuff_beatz_v145_contract_setup',39);
function tuff_beatz_v145_contract_box($post){$c=tuff_beatz_v145_contract_data($post->ID);$proposal_a=function_exists('tuff_beatz_v14_proposal_acceptance')?tuff_beatz_v14_proposal_acceptance($post->ID):array();wp_nonce_field('tb_v145_contract_'.$post->ID,'tb_v145_contract_nonce');echo '<div><p><strong>Proposal prerequisite:</strong> '.esc_html(($proposal_a['decision']??'')==='accepted'?'Accepted':'Not accepted').'</p><p><label><strong>Agreement #</strong></label><br><input style="width:100%" name="tb_v145_contract_number" value="'.esc_attr($c['number']??('TBC-'.str_pad($post->ID,5,'0',STR_PAD_LEFT))).'"></p><p><label><strong>Agreement Terms</strong></label><br><textarea style="width:100%;min-height:260px" name="tb_v145_contract_terms">'.esc_textarea($c['terms']??'').'</textarea></p><p><label><strong>Effective / Start Notes</strong></label><br><textarea style="width:100%;min-height:70px" name="tb_v145_contract_start_notes">'.esc_textarea($c['start_notes']??'').'</textarea></p><p><label><strong>Expires</strong></label><br><input type="date" name="tb_v145_contract_expires" value="'.esc_attr($c['expires']??'').'"></p><p><small>This workflow records platform acceptance of a versioned agreement. It is not represented as a certified electronic-signature service.</small></p></div>';}
function tuff_beatz_v145_contract_metabox(){add_meta_box('tb_v145_contract','Studio Business OS — Contract','tuff_beatz_v145_contract_box','tb_opportunity','normal','high');add_meta_box('tb_v145_contract_delivery','Contract Delivery','tuff_beatz_v145_contract_delivery_box','tb_opportunity','side','high');}
add_action('add_meta_boxes_tb_opportunity','tuff_beatz_v145_contract_metabox');
function tuff_beatz_v145_contract_delivery_box($post){$c=tuff_beatz_v145_contract_data($post->ID);$a=tuff_beatz_v145_contract_acceptance($post->ID);if(!$c){echo '<p>Create and save the agreement first.</p>';return;}echo '<p><strong>Status:</strong> '.esc_html(strtoupper($c['status']??'draft')).'</p><p><strong>Version:</strong> '.esc_html((int)($c['revision']??1)).'</p>';if($a)echo '<p><strong>Accepted:</strong><br>'.esc_html($a['name']??'Client').'<br><small>'.esc_html($a['accepted_at']??'').'</small></p>';echo '<p><a class="button button-primary" target="_blank" href="'.esc_url(tuff_beatz_v145_contract_url($post->ID)).'">Preview Client Agreement</a></p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="tb_v145_contract_mark_sent"><input type="hidden" name="opportunity_id" value="'.esc_attr($post->ID).'">';wp_nonce_field('tb_v145_contract_sent_'.$post->ID,'tb_v145_contract_sent_nonce');echo '<button class="button" type="submit">Mark Contract Sent</button></form>';}
function tuff_beatz_v145_save_contract($id,$post){if($post->post_type!=='tb_opportunity'||(defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE))return;if(!isset($_POST['tb_v145_contract_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tb_v145_contract_nonce'])),'tb_v145_contract_'.$id)||!current_user_can('edit_post',$id))return;$old=tuff_beatz_v145_contract_data($id);$c=array('number'=>sanitize_text_field(wp_unslash($_POST['tb_v145_contract_number']??'')),'terms'=>sanitize_textarea_field(wp_unslash($_POST['tb_v145_contract_terms']??'')),'start_notes'=>sanitize_textarea_field(wp_unslash($_POST['tb_v145_contract_start_notes']??'')),'expires'=>sanitize_text_field(wp_unslash($_POST['tb_v145_contract_expires']??'')),'updated_at'=>current_time('mysql'));$proposal=function_exists('tuff_beatz_v14_proposal_data')?tuff_beatz_v14_proposal_data($id):array();$finger=hash('sha256',wp_json_encode(array($c['terms'],$c['start_notes'],$c['expires'],$proposal['version']??'')));$changed=($old['version']??'')&&($old['version']??'')!==$finger;$c['version']=$finger;$c['proposal_version']=$proposal['version']??'';$c['revision']=max(1,(int)($old['revision']??0)+($changed?1:0));$c['status']=(!$changed&&isset($old['status']))?$old['status']:'draft';if($changed){delete_post_meta($id,'_tb_v145_contract_acceptance');$c['status']='draft';if(function_exists('tuff_beatz_v14_add_opportunity_activity'))tuff_beatz_v14_add_opportunity_activity($id,'contract','Contract revised to version '.$c['revision']);}update_post_meta($id,'_tb_v145_contract',$c);}
add_action('save_post_tb_opportunity','tuff_beatz_v145_save_contract',35,2);
function tuff_beatz_v145_contract_access($id,$token){if(get_post_type($id)!=='tb_opportunity')return false;if(current_user_can('edit_post',$id))return true;$saved=(string)get_post_meta($id,'_tb_v145_contract_token',true);return $saved&&$token&&hash_equals($saved,$token);}
function tuff_beatz_v145_contract_mark_sent(){ $id=(int)($_POST['opportunity_id']??0);if(!$id||!current_user_can('edit_post',$id))wp_die('Not allowed.',403);check_admin_referer('tb_v145_contract_sent_'.$id,'tb_v145_contract_sent_nonce');$proposal_a=function_exists('tuff_beatz_v14_proposal_acceptance')?tuff_beatz_v14_proposal_acceptance($id):array();$c=tuff_beatz_v145_contract_data($id);if(($proposal_a['decision']??'')!=='accepted'||!$c){wp_safe_redirect(add_query_arg('contract_error','proposal',get_edit_post_link($id,'url')));exit;}$c['status']='sent';$c['sent_at']=current_time('mysql');update_post_meta($id,'_tb_v145_contract',$c);update_post_meta($id,'_tb_v14_stage','contract');update_post_meta($id,'_tb_v14_probability',75);if(function_exists('tuff_beatz_v14_add_opportunity_activity'))tuff_beatz_v14_add_opportunity_activity($id,'contract','Contract marked sent');wp_safe_redirect(get_edit_post_link($id,'url'));exit;}
add_action('admin_post_tb_v145_contract_mark_sent','tuff_beatz_v145_contract_mark_sent');
function tuff_beatz_v145_contract_decision(){ $id=(int)($_POST['opportunity_id']??0);$token=sanitize_text_field(wp_unslash($_POST['contract_token']??''));$url=add_query_arg(array('opportunity'=>$id,'contract_token'=>rawurlencode($token)),home_url('/contract/'));if(!$id||!tuff_beatz_v145_contract_access($id,$token))wp_die('Contract access denied.',403);if(!isset($_POST['tb_v145_contract_decision_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tb_v145_contract_decision_nonce'])),'tb_v145_contract_decision_'.$id))wp_die('Contract verification failed.',403);$c=tuff_beatz_v145_contract_data($id);$proposal=function_exists('tuff_beatz_v14_proposal_data')?tuff_beatz_v14_proposal_data($id):array();$proposal_a=function_exists('tuff_beatz_v14_proposal_acceptance')?tuff_beatz_v14_proposal_acceptance($id):array();if(!$c||($proposal_a['decision']??'')!=='accepted'||($c['status']??'')!=='sent'){wp_safe_redirect(add_query_arg('contract_state','unavailable',$url));exit;}if(($c['proposal_version']??'')!==($proposal['version']??'')||($proposal_a['proposal_version']??($proposal_a['version']??''))!==($proposal['version']??'')){wp_safe_redirect(add_query_arg('contract_state','proposal-changed',$url));exit;}if(!empty($c['expires'])&&strtotime($c['expires'].' 23:59:59')<current_time('timestamp')){wp_safe_redirect(add_query_arg('contract_state','expired',$url));exit;}$decision=sanitize_key($_POST['decision']??'');if(!in_array($decision,array('accepted','declined'),true)){wp_safe_redirect($url);exit;}$existing=tuff_beatz_v145_contract_acceptance($id);if($existing){wp_safe_redirect(add_query_arg('contract_state',sanitize_key($existing['decision']??'recorded'),$url));exit;}$name=trim(sanitize_text_field(wp_unslash($_POST['client_name']??'')));$email=sanitize_email(wp_unslash($_POST['client_email']??''));if(strlen($name)<2||!is_email($email)){wp_safe_redirect(add_query_arg('contract_state','identity-required',$url));exit;}if($decision==='accepted'&&empty($_POST['acknowledge'])){wp_safe_redirect(add_query_arg('contract_state','acknowledgement-required',$url));exit;}$record=array('acceptance_id'=>wp_generate_uuid4(),'decision'=>$decision,'contract_version'=>$c['version']??'','contract_revision'=>(int)($c['revision']??1),'proposal_version'=>$c['proposal_version']??'','name'=>$name,'email'=>$email,'acknowledged'=>$decision==='accepted'?1:0,'accepted_at'=>current_time('mysql'),'ip_hash'=>hash('sha256',($_SERVER['REMOTE_ADDR']??'').'|'.wp_salt('auth')));add_post_meta($id,'_tb_v145_contract_acceptance_entry',$record,false);$history=tuff_beatz_v145_contract_acceptance_history($id);$history[]=$record;update_post_meta($id,'_tb_v145_contract_acceptance_history',$history);update_post_meta($id,'_tb_v145_contract_acceptance',$record);$c['status']=$decision;update_post_meta($id,'_tb_v145_contract',$c);if($decision==='accepted'){update_post_meta($id,'_tb_v14_stage','deposit-due');update_post_meta($id,'_tb_v14_probability',90);if(function_exists('tuff_beatz_v14_add_opportunity_activity'))tuff_beatz_v14_add_opportunity_activity($id,'contract','Contract accepted by '.$record['name'].' — acceptance '.$record['acceptance_id']);}elseif(function_exists('tuff_beatz_v14_add_opportunity_activity'))tuff_beatz_v14_add_opportunity_activity($id,'contract','Contract declined by '.$record['name'].' — decision '.$record['acceptance_id']);wp_mail(get_option('admin_email'),'TUFF BEATZ — Contract '.ucfirst($decision),get_the_title($id).' — '.$record['name'].' <'.$record['email'].'>');wp_safe_redirect(add_query_arg('contract_state',$decision,$url));exit;}
add_action('admin_post_nopriv_tb_v145_contract_decision','tuff_beatz_v145_contract_decision');add_action('admin_post_tb_v145_contract_decision','tuff_beatz_v145_contract_decision');
